const x=$json;
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel))
 throw new Error('renderer_invalid_channel');
if(!x.verified_result || x.verified_result.verified!==true)
 throw new Error('renderer_requires_verified_result');
if(x.verified_result.success!==true)
 throw new Error('renderer_cannot_render_success_from_failed_result');
const lang=x.language||'tn', script=x.script||'latin';
if(!['tn','fr','ar','en'].includes(lang)) throw new Error('renderer_invalid_language');
if(!['latin','arabic'].includes(script)) throw new Error('renderer_invalid_script');
return [{json:{...x,language:lang,script,register:x.register||'casual'}}];

const x=$json, r=x.verified_result;
const o=r.order||r.checkout_snapshot||r.cart||r.promotion||null;

// Renderer receives verified facts only. Reject obvious unsafe fields if they
// accidentally enter the renderer contract.
const forbidden=['api_key','authorization','access_token','password','otp','cvv',
  'card_number','pan','cart_token','nonce','consumer_secret','client_secret'];
const raw=JSON.stringify(r).toLowerCase();
for(const k of forbidden) if(raw.includes(k)) throw new Error(`renderer_forbidden_field_${k}`);

if(o?.payment_method==='cod' && o?.payment_status==='paid')
  throw new Error('renderer_cod_paid_conflict');

return [{json:{...x,renderable_fact_set:r}}];

const x=$json, r=x.renderable_fact_set;
const o=r.order||r.checkout_snapshot||null;
let msg='';

if(o && o.payment_method==='cod' && o.id!==undefined){
  msg=`Commande confirmée #${o.id}. Paiement à la livraison (COD).`;
  if(o.total!==null && o.total!==undefined)
    msg += ` Total: ${o.total} ${o.currency||'TND'}.`;
} else if(o && r.operation==='checkout_validate'){
  msg=`Le panier est prêt à être confirmé. Total vérifié: ${o.total} ${o.currency||'TND'}. Paiement: ${o.payment_method||'COD'}.`;
} else if(r.promotion){
  msg=r.promotion.customer_message || 'La promotion a été vérifiée.';
} else if(r.cart){
  msg='Panier mis à jour.';
} else {
  msg='Votre demande a été vérifiée.';
}

// This default is intentionally conservative. Language/script adaptation must
// happen through a controlled renderer/template layer before production.
// Do not ask the LLM to freely rewrite verified transactional facts.
return [{json:{
  channel:x.channel,language:x.language,script:x.script,register:x.register,
  customer_message:msg,
  source:'verified_transactional_result',
  facts:r
}}];

const x=$json;
if(x.script==='latin'){
  // Arabic Unicode block check. Latin/Tunisian Arabizi responses must not
  // silently switch to Arabic script.
  if(/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]/.test(x.customer_message))
    throw new Error('renderer_script_violation_latin');
}
return [{json:x}];

const x=$json;
if(typeof x.customer_message!=='string'||!x.customer_message.trim())
 throw new Error('renderer_empty_message');

// Never expose internal structured result wholesale to the channel.
const publicFields={channel:x.channel,language:x.language,script:x.script,
register:x.register,customer_message:x.customer_message};
return [{json:publicFields}];
